toolCall.argumentsJson:
{"CommandLine":"$appJs = (Invoke-WebRequest -Uri "https://blitz.gg/_app/immutable/entry/app.D6qGD1rz.js" -UseBasicParsing -TimeoutSec 10).Content
$nodes = [regex]::Matches($appJs, 'nodes/\d+\.[^"''\s)]+\.js') | Select-Object -ExpandProperty Value -Unique
Write-Host "Nodes count: $($nodes.Count)"
$html = (Invoke-WebRequest -Uri "https://blitz.gg/lol/champions/Aatrox/build" -UseBasicParsing -TimeoutSec 10).Content
$nodeIds = [regex]::Match($html, 'node_ids:\s*\[([^\]]+)\]').Groups[1].Value
Write-Host "Active node_ids on build page: $nodeIds"
foreach ($nid in ($nodeIds -split ',' | ForEach-Object { $_.Trim() })) {
    $nPath = $nodes | Where-Object { $_ -match "^nodes/$nid\." }
    if ($nPath) {
        $nJs = (Invoke-WebRequest -Uri "https://blitz.gg/_app/immutable/$nPath" -UseBasicParsing -TimeoutSec 10).Content
        Write-Host "Node $nid ($nPath): len=$($nJs.Length)"
        $chunks = [regex]::Matches($nJs, '\.\./chunks/[^"''\s)]+\.js') | Select-Object -ExpandProperty Value -Unique
        foreach ($c in $chunks) {
            $cUrl = "https://blitz.gg/_app/immutable/" + ($c -replace '^\.\./', '')
            $cJs = (Invoke-WebRequest -Uri $cUrl -UseBasicParsing -TimeoutSec 10).Content
            if ($cJs -match 'champion_builds' -or $cJs -match 'Matchup Builds') {
                Write-Host "  FOUND in chunk $cUrl"
                [regex]::Matches($cJs, '.{0,100}(champion_builds|match_up_champion_id|Matchup Builds).{0,160}') | Select-Object -ExpandProperty Value | ForEach-Object { Write-Host "    $_" }
            }
        }
    }
}","WaitMsBeforeAsync":10000,"toolSummary":"Inspect active SvelteKit nodes and chunks on Blitz.gg build page"}
